#[derive(Debug)]
pub enum ConfigError {
    Io(std::io::Error),
    Format(toml::de::Error),
}

fn load_config() -> Result<Config, ConfigError> {
    let content = std::fs::read_to_string("config.toml").map_err(ConfigError::Io)?;
    toml::from_str(&content).map_err(ConfigError::Format)
